    {
        try
        {
            var created = await TaskService.CreateTaskAsync(stub.Title, stub.Assignee, stub.Priority, stub.DueDate);
            allTasks.Add(created);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }
}

